local Players = game:GetService("Players");
local localPlayer = Players.LocalPlayer;
local targetParent = workspace.Live:WaitForChild(localPlayer.Name);
local foldersToDelete = {"DASHCD","SideDashCounter","ForwardDashCD","DashPunchCD","DontAllowBlocking","RecentSideDash","TRUECANTSIDEDASH","CantPunchOnCLIENT","DownSlamCD","RecentStun","RecentStunNoAction","recentdashok","RagdollCancelCD"};
local function removeFolders()
	for _, folderName in pairs(foldersToDelete) do
		local folder = targetParent:FindFirstChild(folderName);
		if folder then
			folder:Destroy();
		end
	end
end
game:GetService("RunService").Heartbeat:Connect(removeFolders);
